import ast, base64, difflib, hashlib, json, re
payload=json.loads(base64.b64decode(""))
before,after=payload["before"],payload["after"]
trees=[ast.parse(x) for x in (before,after)]
for tree in trees: compile(tree,"source-only.py","exec")
inverse=after
for old,new in reversed(payload["replacements"]):
    assert inverse.count(new)==1
    inverse=inverse.replace(new,old,1)
assert inverse==before
def definitions(source,tree):
    lines=source.splitlines(keepends=True)
    return {n.name:"".join(lines[n.lineno-1:n.end_lineno]) for n in tree.body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
od,nd=definitions(before,trees[0]),definitions(after,trees[1])
assert set(od)==set(nd)
unchanged=[k for k in od if k!="main"]
assert all(od[k]==nd[k] for k in unchanged)
constants={"TIMING_PREFIX","MAX_TIMING_LINE","U128_MAX","U64_MAX","TIMING_KEYS","BUCKET_KEYS","COUNT_KEYS","TIME_KEYS","TIMING_PAIRS"}
defs={"Refused","timing_object_pairs","timing_integer","timing_noninteger","checked_timing_uint","parse_timing_marker"}
def selected(tree):
    body=[]
    for n in tree.body:
        if isinstance(n,ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0],ast.Name) and n.targets[0].id in constants: body.append(n)
        elif isinstance(n,(ast.FunctionDef,ast.ClassDef)) and n.name in defs: body.append(n)
    ns={"json":json,"re":re}
    exec(compile(ast.fix_missing_locations(ast.Module(body=body,type_ignores=[])),"selected-pure-parser.py","exec"),ns)
    return ns
old,new=map(selected,trees)
pairs=set(new["TIMING_PAIRS"])
cold={("cold_native_ha",x["label"]) for x in payload["labels"]}
assert len(old["TIMING_PAIRS"])==50 and len(pairs)==70 and pairs==set(old["TIMING_PAIRS"])|cold and len(cold)==20
def bucket(scope,phase):
    return dict(zip(new["BUCKET_KEYS"],(scope,phase,1,0,1,0,10,10,100,90,100,90)))
def line(bs,request_class="ordinary"):
    obj=dict(zip(new["TIMING_KEYS"],("heptabao.native-ha.request-failure-timing.v1",request_class,False,503,50,1000,950,64,False,bs)))
    return new["TIMING_PREFIX"]+json.dumps(obj,separators=(",",":")).encode("ascii")+b"\n"
checks=[]
for scope,phase in sorted(cold):
    parsed=new["parse_timing_marker"](line([bucket(scope,phase)]))
    assert parsed["phases"][0]["phase"]==phase and parsed["phases"][0]["completed"]=="1"
    checks.append({"case":"new_static_pair_"+phase,"passed":True})
def refused(ns,raw,expected):
    try: ns["parse_timing_marker"](raw)
    except ns["Refused"] as e: assert str(e)==expected
    else: raise AssertionError("unexpected accept")
refused(old,line([bucket("cold_native_ha","load")]),"unknown_static_timing_label_pair")
checks.append({"case":"old_source_rejects_new_pair","passed":True})
refused(new,line([bucket("fresh_ingress_permission","load")]),"unknown_static_timing_label_pair")
checks.append({"case":"cross_scope_label_rejected","passed":True})
refused(new,line([bucket("cold_native_ha","not_a_source_phase")]),"unknown_static_timing_label_pair")
checks.append({"case":"unknown_cold_label_rejected","passed":True})
assert len(new["parse_timing_marker"](line([bucket(*x) for x in sorted(pairs)[:64]]))["phases"])==64
checks.append({"case":"original_64_bucket_cap_accepts_64","passed":True})
refused(new,line([bucket(*x) for x in sorted(pairs)[:65]]),"invalid_timing_bucket_count")
checks.append({"case":"70_allowed_pairs_does_not_allow_65_buckets","passed":True})
refused(new,line([],request_class="snapshot_test"),"invalid_timing_report_static_fields")
checks.append({"case":"normal_fixture_classes_do_not_expand_to_ci_test_class","passed":True})
diff="".join(difflib.unified_diff(before.splitlines(keepends=True),after.splitlines(keepends=True),fromfile="base-phaseb3cb-node1-projector.py",tofile="candidate-df026-node2-projector.py"))
result={"schema":"heptabao.df026-cold-log-projector-source-components.v1","passed":True,"checks":checks,"checks_passed":len(checks),"full_sources_ast_compiled":2,"whole_module_executed":False,"host_actions":0,"product_requests":0,"native_files_read":0,"functions_and_classes_unchanged_except_main":unchanged,"literal_replacements_exact_inverse":len(payload["replacements"]),"allowed_pairs_before":50,"allowed_pairs_after":70,"actual_bucket_cap":64,"diff_hunks":sum(x.startswith("@@") for x in diff.splitlines()),"before_sha256":hashlib.sha256(before.encode()).hexdigest(),"after_sha256":hashlib.sha256(after.encode()).hexdigest()}
print(json.dumps({"result":result,"diff":diff},sort_keys=True,separators=(",",":")))
